package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ConsecutiveFailuresVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property consecutive failures of observed probe ")
  void test_consecutive_failures_v_o_builder() {
    Assertions.assertFalse(ConsecutiveFailuresVO.nullValue().getConsecutiveFailures().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ConsecutiveFailuresVO.tryFrom(null).getConsecutiveFailures().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, ConsecutiveFailuresVO.from(1).getConsecutiveFailures().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ConsecutiveFailuresVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ConsecutiveFailuresVO.from(1).toString());
  }
}
